// ignore_for_file: avoid_dynamic_calls
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:phosphor_flutter/phosphor_flutter.dart';
import 'package:ural_erp/core/theme/app_colors.dart';
import 'package:ural_erp/core/constants/app_constants.dart';
import 'package:ural_erp/core/utils/financial_utils.dart';
// Note: Some classes (Product, Category, Unit) are generated by Drift in database.g.dart
// If they show as undefined, it is because build_runner is still generating code.
import 'package:ural_erp/data/providers/providers.dart';
import 'package:ural_erp/presentation/widgets/searchable_unit_selection_dialog.dart';

class PurchaseInvoiceItemsTable extends ConsumerWidget {
  final List<Map<String, dynamic>> items;
  final Function(int index, Map<String, dynamic> updatedItem) onItemChanged;
  final Function(int index) onItemRemoved;
  final String Function(int? categoryId) getCategoryName;

  const PurchaseInvoiceItemsTable({
    super.key,
    required this.items,
    required this.onItemChanged,
    required this.onItemRemoved,
    required this.getCategoryName,
  });

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    if (items.isEmpty) {
      return Container(
        height: 100,
        decoration: BoxDecoration(
          border: Border.all(color: AppColors.border),
          borderRadius: BorderRadius.circular(8),
        ),
        child: const Center(
          child: Text(
            'لم يتم إضافة أصناف بعد',
            style: TextStyle(color: AppColors.textMuted),
          ),
        ),
      );
    }

    return Card(
      child: SingleChildScrollView(
        scrollDirection: Axis.horizontal,
        child: DataTable(
          columnSpacing: 12,
          columns: const [
            DataColumn(label: Text('الصنف')),
            DataColumn(label: Text('الوحدة')),
            DataColumn(label: Text('التصنيف')),
            DataColumn(label: Text('الكمية')),
            DataColumn(label: Text('سعر الشراء')),
            DataColumn(label: Text('الضريبة %')),
            DataColumn(label: Text('قيمة الضريبة')),
            DataColumn(label: Text('الإجمالي')),
            DataColumn(label: Text('')),
          ],
          rows: items.asMap().entries.map((entry) {
            final index = entry.key;
            final item = entry.value;
            final taxRate = (item['taxRate'] as num? ?? 0).toDouble();
            final taxAmount = (item['taxAmount'] as num? ?? 0).toDouble();
            final lineTotal = (item['lineTotal'] as num? ?? 0).toDouble();
            // Per-row VAT toggle: an invoice may mix taxable and exempt items
            // (e.g. unprocessed foodstuff vs packaged goods). If the map
            // already carries the flag use it, otherwise derive from the
            // stored rate so existing invoices load with the checkbox set
            // correctly (>0% ⇒ enabled).
            final taxEnabled = (item['taxEnabled'] as bool?) ?? (taxRate > 0);

            return DataRow(
              cells: [
                DataCell(Text(item['productName'] as String? ?? '-')),
                DataCell(
                   InkWell(
                    onTap: () async {
                      final productRepo = ref.read(productRepositoryProvider);
                      final units = await productRepo.getProductUnits(item['productId'] as int);
                      
                      if (units.isEmpty) return;

                      if (context.mounted) {
                        // Return type will be resolved after database.g.dart is generated
                        final selectedUnit = await showDialog<dynamic>(
                          context: context,
                          builder: (context) => SearchableUnitSelectionDialog(
                            units: units,
                            currentUnitName: item['selectedUnitName'] as String?,
                          ),
                        );

                        if (selectedUnit != null) {
                          final updatedItem = Map<String, dynamic>.from(item);
                          updatedItem['selectedUnitName'] = selectedUnit.unitName;
                          updatedItem['quantityInBase'] = selectedUnit.quantityInBase;
                          onItemChanged(index, updatedItem);
                        }
                      }
                    },
                    child: Container(
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                      decoration: BoxDecoration(
                        color: AppColors.info.withValues(alpha: 0.1),
                        borderRadius: BorderRadius.circular(4),
                      ),
                      child: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Text(
                            (item['selectedUnitName'] as String?) ?? 'قطعة',
                            style: const TextStyle(
                              color: AppColors.info, 
                              fontWeight: FontWeight.bold
                            ),
                          ),
                          const Icon(PhosphorIconsBold.caretDown, size: 12, color: AppColors.info),
                        ],
                      ),
                    ),
                  ),
                ),
                DataCell(Text(getCategoryName(item['categoryId'] as int?))),
                DataCell(
                  SizedBox(
                    width: 60,
                    child: TextFormField(
                      key: ValueKey('inv_qty_${index}_${item['productId']}'),
                      initialValue: (item['quantity'] as num? ?? 1.0).toDouble().toStringAsFixed(0),
                      decoration: const InputDecoration(isDense: true, border: OutlineInputBorder()),
                      keyboardType: const TextInputType.numberWithOptions(decimal: true),
                      onChanged: (val) {
                        final qty = double.tryParse(val) ?? 1.0;
                        final updatedItem = Map<String, dynamic>.from(item);
                        final unitCost = (item['unitCost'] as num? ?? 0).toDouble();
                        final newLineTotal = FinancialUtils.calculateLineSubtotal(qty, unitCost);
                        final newTaxAmount = taxEnabled
                            ? FinancialUtils.calculateTaxAmount(newLineTotal, taxRate)
                            : 0.0;
                        updatedItem['quantity'] = qty;
                        updatedItem['lineTotal'] = newLineTotal;
                        updatedItem['taxAmount'] = newTaxAmount;
                        onItemChanged(index, updatedItem);
                      },
                    ),
                  ),
                ),
                DataCell(
                  SizedBox(
                    width: 80,
                    child: TextFormField(
                      key: ValueKey('inv_cost_${index}_${item['productId']}'),
                      initialValue: (item['unitCost'] as num? ?? 0).toDouble().toStringAsFixed(AppConstants.decimalPlaces),
                      decoration: const InputDecoration(isDense: true, border: OutlineInputBorder()),
                      keyboardType: const TextInputType.numberWithOptions(decimal: true),
                      onChanged: (val) {
                        final cost = double.tryParse(val) ?? 0.0;
                        final updatedItem = Map<String, dynamic>.from(item);
                        final qty = (item['quantity'] as num? ?? 1.0).toDouble();
                        final newLineTotal = FinancialUtils.calculateLineSubtotal(qty, cost);
                        final newTaxAmount = taxEnabled
                            ? FinancialUtils.calculateTaxAmount(newLineTotal, taxRate)
                            : 0.0;
                        updatedItem['unitCost'] = cost;
                        updatedItem['lineTotal'] = newLineTotal;
                        updatedItem['taxAmount'] = newTaxAmount;
                        onItemChanged(index, updatedItem);
                      },
                    ),
                  ),
                ),
                DataCell(
                  SizedBox(
                    width: 140,
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Checkbox(
                          value: taxEnabled,
                          visualDensity: VisualDensity.compact,
                          onChanged: (val) {
                            final enabled = val ?? false;
                            final updatedItem = Map<String, dynamic>.from(item);
                            final qty = (item['quantity'] as num? ?? 1.0).toDouble();
                            final unitCost = (item['unitCost'] as num? ?? 0).toDouble();
                            final subtotal = FinancialUtils.calculateLineSubtotal(qty, unitCost);
                            updatedItem['taxEnabled'] = enabled;
                            updatedItem['taxAmount'] = enabled
                                ? FinancialUtils.calculateTaxAmount(subtotal, taxRate)
                                : 0.0;
                            onItemChanged(index, updatedItem);
                          },
                        ),
                        Expanded(
                          child: TextFormField(
                            key: ValueKey('inv_tax_rate_${index}_${item['productId']}_$taxEnabled'),
                            enabled: taxEnabled,
                            initialValue: taxRate.toStringAsFixed(0),
                            decoration: const InputDecoration(
                              isDense: true,
                              border: OutlineInputBorder(),
                              suffixText: '%',
                              contentPadding: EdgeInsets.symmetric(horizontal: 6, vertical: 8),
                            ),
                            keyboardType: const TextInputType.numberWithOptions(decimal: true),
                            onChanged: (val) {
                              final rate = double.tryParse(val) ?? 0.0;
                              final updatedItem = Map<String, dynamic>.from(item);
                              final qty = (item['quantity'] as num? ?? 1.0).toDouble();
                              final unitCost = (item['unitCost'] as num? ?? 0).toDouble();
                              final subtotal = FinancialUtils.calculateLineSubtotal(qty, unitCost);
                              updatedItem['taxRate'] = rate;
                              updatedItem['taxAmount'] = FinancialUtils.calculateTaxAmount(subtotal, rate);
                              onItemChanged(index, updatedItem);
                            },
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
                DataCell(Text(taxAmount.toStringAsFixed(AppConstants.decimalPlaces))),
                DataCell(Text('${lineTotal.toStringAsFixed(AppConstants.decimalPlaces)} ${AppConstants.currencySymbolEn}')),
                DataCell(
                  IconButton(
                    icon: const Icon(PhosphorIconsBold.trash, color: AppColors.error, size: 18),
                    onPressed: () => onItemRemoved(index),
                  ),
                ),
              ],
            );
          }).toList(),
        ),
      ),
    );
  }
}